ruleBookInfo.intro:
@js:
var names = [];
var tm = result.match(/data-toggle="tab"[^>]*>([^<]+)</g);
if (tm) {
    for (var i = 0; i < tm.length; i++) {
        var mm = tm[i].match(/>([^<]+)</);
        if (mm) names.push(mm[1]);
    }
}
var n = names.length;
if (n === 0) {
    n = (result.match(/<ul class="stui-content__playlist/g) || []).length;
    for (var z = 0; z < n; z++) {
        names.push('线路' + (z + 1));
    }
}
var xu = '0';
try {
    var cv = book.getVariable('custom');
    if (cv != null && cv != '') {
        xu = String(cv);
    }
} catch(e) {}
if (xu == '0' || xu == '') {
    var ov = String(book.variable || '');
    if (ov != '') {
        xu = ov;
    }
}
var list = '';
for (var i2 = 0; i2 < names.length; i2++) {
    list += '◖' + i2 + '◗' + names[i2] + ' ';
}
var lineInfo = '【线路列表】' + list.trim() + '\n当前来源◖' + xu + '◗\n（右上角书籍变量填 0-' + (n - 1) + ' 刷新切换线路）';
var desc = '';
var dcMatch = result.match(/<span class="detail-content" style="display: none;">([\s\S]*?)<\/span>/);
if (dcMatch) {
    desc = dcMatch[1].trim();
}
if (!desc) {
    var dsMatch = result.match(/<span class="detail-sketch">([\s\S]*?)<\/span>/);
    if (dsMatch) {
        desc = dsMatch[1].trim();
    }
}
if (!desc) {
    desc = java.getString('meta[name="description"]@content') || '';
}
lineInfo + '\n\n📖 简介：' + desc;

ruleContent.content:
@js:
var out = '';
var dbg = '';
var UA = 'Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36';
var REF = 'https://www.kalamanhua.com/';
var CDN = 'https://image.kalaimg.top';

var logd = function (m) {
  try { java.log('KALA' + m); } catch (e0) {}
};

var bodyOf = function (r) {
  if (!r) { return ''; }
  try { if (typeof r.body === 'function') { return String(r.body()); } } catch (e1) {}
  try { if (typeof r.body === 'string') { return r.body; } } catch (e2) {}
  try { return String(r); } catch (e3) { return ''; }
};

var got = function (s) {
  if (!s) { return false; }
  return s.indexOf('data-src') >= 0;
};

var tryGet = function (u, h) {
  try { return bodyOf(java.get(u, h)); } catch (e) { dbg += '|gE'; return ''; }
};

var tryAjax = function (u) {
  try { return String(java.ajax(u)); } catch (e) { dbg += '|aE'; return ''; }
};

var pickTok = function (s) {
  if (!s) { return ''; }
  var m = s.match(/(?:var|const|let) token = '([^']+)'/);
  if (m) { return m[1]; }
  var k = s.indexOf('token');
  if (k < 0) { return ''; }
  var q1 = s.indexOf("'", k);
  if (q1 >= 0) {
    var q2 = s.indexOf("'", q1 + 1);
    if (q2 > q1) { return s.substring(q1 + 1, q2); }
  }
  q1 = s.indexOf('"', k);
  if (q1 >= 0) {
    var q3 = s.indexOf('"', q1 + 1);
    if (q3 > q1) { return s.substring(q1 + 1, q3); }
  }
  return '';
};

var html = String(result);
if (html.indexOf('player_aaaa') < 0) {
  var t0 = pickTok(html);
  if (t0) {
    var h2 = tryAjax(baseUrl + '?cf_verify=' + t0);
    if (!h2) { h2 = tryGet(baseUrl + '?cf_verify=' + t0, {Referer: REF, 'User-Agent': UA}); }
    dbg += '|heal=' + h2.length;
    if (h2.indexOf('player_aaaa') >= 0) { html = h2; }
  }
}

var um = html.match(/"url":"([0-9a-f]+)"/);
var enc = um ? um[1] : '';
var tk = '';
var page = '';

if (enc) {
  var minUrl = CDN + '/play/min/' + enc;

  page = tryGet(minUrl, {Referer: REF, 'User-Agent': UA});
  dbg += '|p1=' + page.length;

  if (!got(page)) {
    page = tryAjax(minUrl);
    dbg += '|a1=' + page.length;
  }

  if (!got(page)) {
    tk = pickTok(page);
    dbg += '|tk=' + (tk ? tk.length : 0);
  }

  if (!got(page)) {
    if (tk) {
      var q = minUrl + '?cf_verify=' + tk;
      page = tryGet(q, {Referer: REF, 'User-Agent': UA, Cookie: 'omo_token=' + tk});
      dbg += '|p2=' + page.length;
      if (!got(page)) {
        page = tryAjax(q);
        dbg += '|a2=' + page.length;
      }
      if (!got(page)) {
        page = tryGet(minUrl, {Referer: REF, 'User-Agent': UA, Cookie: 'omo_token=' + tk});
        dbg += '|p3=' + page.length;
      }
    }
  }

  var imgs = page.match(/data-src="[^"]+"/g);
  if (imgs) {
    for (var i = 0; i < imgs.length; i++) {
      var s = imgs[i].substring(10, imgs[i].length - 1);
      var full = CDN + s;
      if (full.indexOf('cf_verify=') < 0) {
        if (tk) { full += '?cf_verify=' + tk; }
      }
      out += '<img src="' + full + '">';
    }
    dbg += '|img=' + imgs.length;
  } else {
    out = 'ERR:no-img[' + page.length + ']' + dbg + '|h=' + page.substring(0, 40);
  }
} else {
  out = 'ERR:no-enc' + dbg + '|h=' + html.substring(0, 40);
}

logd(dbg);
out;

